import yaml
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_17/projects/recovery_aware_struct_prune/registry.yaml') as f:
    data = yaml.safe_load(f)

# Check structure
if isinstance(data, dict):
    keys = list(data.keys())[:5]
    print(f'Top-level type: dict, {len(data)} keys')
    print(f'Sample keys: {keys}')
    for k in keys:
        v = data[k]
        if isinstance(v, dict):
            print(f'  {k}: keys={list(v.keys())[:8]}')
        else:
            print(f'  {k}: type={type(v).__name__}')
elif isinstance(data, list):
    print(f'Top-level type: list, {len(data)} items')
    if data:
        print(f'First item: {data[0]}')
